INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913002,'DEMO-SPEAKER','森野便携音箱',189.00,24,'音频','一只手能握住的好声音。织物包覆与随行提环，陪你从书桌走到窗边。','{"images":[{"url":"/media/products/speaker.webp","alt":"森野便携音箱的正面展示"}],"specifications":[{"name":"颜色","value":"鼠尾草绿"},{"name":"连接","value":"蓝牙 5.3"},{"name":"续航","value":"约 12 小时"},{"name":"重量","value":"280 g"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913003,'DEMO-HEADPHONES','云雾头戴耳机',329.00,18,'音频','柔软耳垫包裹双耳，为通勤留一段安静。轻盈的雾紫色，适合长时间聆听。','{"images":[{"url":"/media/products/headphones.webp","alt":"云雾头戴耳机的正面展示"},{"url":"/media/products/headphones-detail.webp","alt":"云雾头戴耳机的材质与结构细节"}],"specifications":[{"name":"颜色","value":"雾紫"},{"name":"佩戴","value":"头戴式"},{"name":"连接","value":"蓝牙 5.3 / AUX"},{"name":"续航","value":"约 40 小时"},{"name":"重量","value":"230 g"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913004,'DEMO-EARBUDS','桃气无线耳机',199.00,35,'音频','轻巧入耳，收进一枚桃色充电盒。出门的口袋里，多一点音乐，少一点负担。','{"images":[{"url":"/media/products/earbuds.webp","alt":"桃气无线耳机的正面展示"}],"specifications":[{"name":"颜色","value":"蜜桃白"},{"name":"佩戴","value":"入耳式"},{"name":"连接","value":"蓝牙 5.3"},{"name":"续航","value":"约 24 小时（含充电盒）"},{"name":"重量","value":"单耳 4.5 g"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913005,'DEMO-KEYBOARD','留白机械键盘',499.00,12,'数码','把桌面留给灵感。紧凑布局、温润键帽与一颗玫瑰色按键，写下每个新想法。','{"images":[{"url":"/media/products/keyboard.webp","alt":"留白机械键盘的正面展示"}],"specifications":[{"name":"颜色","value":"奶白 / 梅紫"},{"name":"布局","value":"75% 配列"},{"name":"连接","value":"USB-C 有线"},{"name":"轴体","value":"线性轴"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913006,'DEMO-LAMP','暮光桌面灯',229.00,16,'居家','一盏柔和的小灯，照亮手边的一页书。圆润灯罩，让晚间的桌面安静下来。','{"images":[{"url":"/media/products/lamp.webp","alt":"暮光桌面灯的正面展示"}],"specifications":[{"name":"颜色","value":"暮光粉"},{"name":"光源","value":"暖白 LED"},{"name":"供电","value":"USB-C"},{"name":"材质","value":"喷涂金属"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913007,'DEMO-MUG','半月陶瓷杯',79.00,0,'居家','白釉与梅紫在杯底相遇。握住宽大的把手，把喝水这件小事，也认真对待。','{"images":[{"url":"/media/products/mug.webp","alt":"半月陶瓷杯的正面展示"}],"specifications":[{"name":"颜色","value":"暖白 / 梅紫"},{"name":"容量","value":"350 mL"},{"name":"材质","value":"陶瓷"},{"name":"清洁","value":"建议手洗"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
INSERT INTO catalog_product (product_id,sku,name,price,stock,category,description,presentation_json) VALUES (913008,'DEMO-BAG','漫游帆布包',129.00,22,'出行','轻装去走走。低调的绿色帆布，装下手机、钥匙和一天的小计划。','{"images":[{"url":"/media/products/bag.webp","alt":"漫游帆布包的正面展示"}],"specifications":[{"name":"颜色","value":"森绿"},{"name":"材质","value":"棉帆布"},{"name":"尺寸","value":"24 × 18 × 7 cm"},{"name":"背法","value":"单肩 / 斜挎"}],"imageNote":"AI 生成的演示图 · 商品及规格均为虚构，仅用于体验购物流程"}');
